export const pathData=points=>points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(3)},${p.y.toFixed(3)}`).join(' ');
export function worldGeometry(part,piece){const g=geometry(part,piece);return {...g,paths:g.paths.map(path=>{const ds=[0];for(let i=1;i<path.points.length;i++)ds.push(ds.at(-1)+Math.hypot(path.points[i].x-path.points[i-1].x,path.points[i].y-path.points[i-1].y));const length=ds.at(-1)||1;return {...path,points:path.points.map((q,i)=>({...transform(q,piece),z:pieceElevation(piece,q,ds[i]/length)}))};}),endpoints:g.endpoints.map((e,i)=>({...transform(e,piece),z:pieceElevation(piece,e,g.paths.some(p=>p.start&&Math.hypot(p.start.x-e.x,p.start.y-e.y)<.001)?0:1),pieceId:piece.id,index:i,brand:part.brand,scale:part.scale,connector:part.geometry.type==='flex'?'bare':'standard'}))};}
export function compatible(a,b){return a.brand===b.brand&&a.scale===b.scale&&(a.connector||'standard')===(b.connector||'standard')&&Math.abs((a.z||0)-(b.z||0))<.5;}
export function connections(pieces,byId,tolerance=.6){
 const endpoints=pieces.flatMap(p=>worldGeometry(byId[p.partId],p).endpoints),connected=new Set(),pairs=[],grid=new Map();
 for(let i=0;i<endpoints.length;i++){const a=endpoints[i],gx=Math.floor(a.x/tolerance),gy=Math.floor(a.y/tolerance);let match=-1;
  for(let dx=-1;dx<=1&&match<0;dx++)for(let dy=-1;dy<=1&&match<0;dy++)for(const j of grid.get(`${gx+dx},${gy+dy}`)||[]){const b=endpoints[j];if(a.pieceId!==b.pieceId&&!connected.has(j)&&compatible(a,b)&&Math.hypot(a.x-b.x,a.y-b.y)<=tolerance&&angleDiff(a.angle,b.angle+180)<.6){match=j;break;}}
  if(match>=0){connected.add(i);connected.add(match);pairs.push([a,endpoints[match]]);}const key=`${gx},${gy}`;if(!grid.has(key))grid.set(key,[]);grid.get(key).push(i);
 }return {endpoints,pairs,open:endpoints.filter((_,i)=>!connected.has(i))};}
export function snapToEndpoint(part,piece,localIndex,target){const e=geometry(part,piece).endpoints[localIndex];if(!e)return piece;const angle=norm(target.angle+180-e.angle*(piece.flip||1));const off=transform(e,{x:0,y:0,angle,flip:piece.flip||1});const dz=(target.z||0)-worldGeometry(part,piece).endpoints[localIndex].z;return {...piece,x:target.x-off.x,y:target.y-off.y,angle,z:(piece.z||0)+dz,zEnd:(piece.zEnd??piece.z??0)+dz};}
export function nearestSnap(part,piece,targets,threshold){let best=null;const g=worldGeometry(part,piece);for(let i=0;i<g.endpoints.length;i++)for(const target of targets){if(!compatible(g.endpoints[i],target)||target.pieceId===piece.id)continue;const d=Math.hypot(g.endpoints[i].x-target.x,g.endpoints[i].y-target.y);if(d<threshold&&(!best||d<best.distance))best={piece:snapToEndpoint(part,piece,i,target),target,distance:d};}return best;}
export function bounds(pieces,byId){const points=pieces.flatMap(p=>worldGeometry(byId[p.partId],p).paths.flatMap(q=>q.points));if(!points.length)return null;return {minX:Math.min(...points.map(p=>p.x)),minY:Math.min(...points.map(p=>p.y)),maxX:Math.max(...points.map(p=>p.x)),maxY:Math.max(...points.map(p=>p.y))};}
export function validateProject(raw,byId){if(!raw||raw.version!==1||typeof raw.name!=='string'||raw.name.length>160||!raw.board||!Array.isArray(raw.pieces)||raw.pieces.length>5000)throw Error('文件不是有效的 枕星 方案，或超过 5000 段轨道。');const finite=(n,lo,hi)=>typeof n==='number'&&Number.isFinite(n)&&n>=lo&&n<=hi;if(!finite(raw.board.width,100,50000)||!finite(raw.board.height,100,50000))throw Error('沙盘尺寸必须在 100–50000 mm 之间。');if(raw.board.outline!==undefined)validateOutline(raw.board.outline,raw.board.width,raw.board.height);const ids=new Set();for(const p of raw.pieces){const part=byId[p.partId];if(!part?.geometry?.type)throw Error(`轨道库不支持型号：${String(p.partId).slice(0,80)}`);if(part.kind==='building'){const d=p.buildingSize||part.dimensions;if(!d||!finite(d.width,1,5000)||!finite(d.depth,1,5000)||(d.height!==undefined&&!finite(d.height,1,5000)))throw Error('建筑尺寸缺失或无效');}if(typeof p.id!=='string'||ids.has(p.id))throw Error('零件编号重复或无效。');ids.add(p.id);if(!finite(p.x,-100000,100000)||!finite(p.y,-100000,100000)||!finite(p.angle,-36000,36000)||![1,-1].includes(p.flip))throw Error('轨道位置或角度无效。');for(const k of ['z','zEnd'])if(p[k]!==undefined&&!finite(p[k],-10000,10000))throw Error('轨道高度无效。');validateSlope(p,geometry(part,p));if(p.tableAngle!==undefined&&(part.geometry.type!=='turntable'||!finite(p.tableAngle,-36000,36000)))throw Error('转盘角度无效');if(p.bend!==undefined&&(part.geometry.type!=='flex'||!finite(p.bend,-180,180)))throw Error('柔性轨角度超出范围');if(p.length!==undefined){if(!part.geometry.minLength||!finite(p.length,part.geometry.minLength,part.geometry.maxLength))throw Error('可变轨道长度超出产品范围。');}}
 return {version:1,name:raw.name,...validateElevation(raw),...validateClosureRecords(raw,byId,geometry),board:{width:raw.board.width,height:raw.board.height,...(raw.board.outline?{outline:validateOutline(raw.board.outline,raw.board.width,raw.board.height)}:{})},pieces:raw.pieces.map(p=>({id:p.id,partId:p.partId,...(p.slope?{slope:{a:p.slope.a,b:p.slope.b,c:p.slope.c}}:{}),...(p.layerId?{layerId:p.layerId}:{}),...(p.endLayerId?{endLayerId:p.endLayerId}:{}),...(p.ramp?{ramp:{from:p.ramp.from,to:p.ramp.to,t0:p.ramp.t0,t1:p.ramp.t1}}:{}),...(byId[p.partId].kind==='building'?{buildingSize:{...(p.buildingSize||byId[p.partId].dimensions)}}:{}),x:p.x,y:p.y,angle:p.angle,flip:p.flip,z:p.z||0,zEnd:p.zEnd??p.z??0,...(p.length===undefined?{}:{length:p.length}),...(p.bend===undefined?{}:{bend:p.bend}),...(p.tableAngle===undefined?{}:{tableAngle:p.tableAngle})}))};}
export function billOfMaterials(pieces,byId){const map=new Map();for(const p of pieces){const part=byId[p.partId];const key=part.brand+'|'+part.sku;if(!map.has(key))map.set(key,{brand:part.brand,sku:part.sku,name:part.name,scale:part.scale,count:0,pack:part.pack||null,source:part.source});map.get(key).count++;}return [...map.values()].sort((a,b)=>a.brand.localeCompare(b.brand)||a.sku.localeCompare(b.sku));}
export function demoProject(byId){const pieces=[];let count=0;const find=(sku)=>Object.values(byId).find(p=>p.brand==='KATO'&&p.scale==='N'&&p.sku===sku);for(const [sku,y] of [['20-132',150],['20-120',183]]){let cursor={x:550,y,angle:0};for(const code of ['20-000','20-000',sku,sku,sku,sku,'20-000','20-000',sku,sku,sku,sku]){const part=find(code);if(!part)continue;const piece={id:'demo-'+(++count),partId:part.id,x:cursor.x,y:cursor.y,angle:cursor.angle,flip:1,z:0,zEnd:0};pieces.push(piece);cursor=worldGeometry(part,piece).endpoints[1];}}
 return {version:1,name:'双环线 · KATO N 轨',board:{width:1800,height:1000},pieces};}
